// ОБРАЗЕЦ: как четвёрка должна валить первую гиену (наше).
//
// Сценарий задан владельцем дословно и целиком:
//   1. все четыре юнита моментально агрятся на первую же попавшуюся псину («леопард» по типу, но
//      выглядит как гиена — так её и зовём);
//   2. никуда не двигаются, не уворачиваются: прямой наводкой бегут к ней и бьют без остановки;
//   3. только когда у кого-то кончается жизнь — пара шагов назад, ждёт ТИК, когда гиена
//      переагрится на другого, и тут же возвращается в бой.
//
// Здесь нет ничего больше: ни выбора добычи по «зубам», ни уклонения, ни мяса, ни отрядов. Это
// эталон, с которым сравнивается обученная сеть, и образец, по которому её можно учить.
//
// Почему приказы отдаются не каждый тик. Для движка новый приказ — сброс автомата: юнит заново
// ищет путь и заново замахивается. Если давить приказ чаще, чем длится удар, он не нанесёт ни
// одного (это уже было в истории проекта: пятеро «били» собаку полторы минуты и не сняли ни
// единицы). Поэтому приказ атаки отдаётся ровно тогда, когда юнит не в атаке или бьёт не того.
import { сПресетом } from './пресеты.js';
import { G, U, UNITS, ITEMS, BI } from '../mem.js';
import { приказ } from '../port/inject.js';
import { проходима, луч, дальность } from './act.js';   // проверка клетки, длина пути, дальнобойность
import * as Кампания from './кампания.js';   // что миссия считает победой: еда, добить племя, дома…
import * as Стройка from './стройка.js';     // конструкторы, заказы в Святилище, тревога по домам
import * as Штаб from './штаб.js';
import * as Ластхит from './ластхит.js';
import * as Т2 from './тирано2.js';   // последний удар — назначенному (прокачка «ровно» или «главный»)           // общие решения поверх отряда: куда идти и что там делать
import { группаВещи, дуэль, тиковНаУдар, статы as статыВида } from './справочник.js'; // оружие/щит/расходник — по списку вещей, а не по полю

// НОМЕР ВЕРСИИ ОБРАЗЦА. Показывается прямо на кнопке «образец» в панели, чтобы с одного взгляда
// было видно, та ли это сборка, что я только что выложил. Просьба владельца: «каждый раз, как
// вносишь изменения, добавляй версию на кнопку, пусть идёт по порядку от одного и до бесконечности,
// так я буду уверен, что кнопка обновилась». Правило простое: правишь этот файл — увеличь число.
export const ВЕРСИЯ = 24;

const КОД = { ИДТИ: 0x0f, АТАКА: 0x1f, СОН: 0x2f, ОХРАНА: 0x3f, ДОБЫЧА: 0x4c, ПАНЕЛЬ: 0xe1 };
const ЗВЕРЬ = (т) => т >= 14 && т <= 23;
// ЯДОВИТЫЕ РАСТЕНИЯ — цветы (тип 24) и грибы (25). Они не ходят, не преследуют и в добычу не
// годятся, зато бьют ПО ПЛОЩАДИ и очень больно: замер на карте Romack — боец в ТРЁХ клетках от
// цветка терял 30 → 14 жизней за полторы секунды. Владелец: «Ромак подохли от цветочков и
// грибочков, туда нельзя идти, надо обходить; у них есть радиус атаки, нельзя приближаться».
// Поэтому вокруг каждого растения запретный круг: туда не ходим ни за добычей, ни за мясом, ни
// убегая, а если оказались внутри — выходим немедленно.
const РАСТЕНИЕ = (т) => т === 24 || т === 25;
const урон = (а, д) => Math.max(1, (Math.max(а - д, 0) >> 4) + (а >> 5) + 1);

/**
 * НАСТОЯЩИЙ УРОН одного по другому — с оружием, щитом и магией, ровно как считает движок
 * (js/port/combat.js, 0x1e758 и 0x1e934).
 *
 * База та же: ((атака − защита) >> 4) + (атака >> 5) + 1. Дальше:
 *   • маги (типы 5–8) бьют заклинанием: к базе прибавляется бонус ИЗ СВОЕЙ ТАБЛИЦЫ ПО ТИПУ ЦЕЛИ,
 *     а щит цели режет урон по другой таблице (у каждого вида магии свои две);
 *   • у кого надето оружие — прибавка из таблицы этого оружия, тоже ПО ТИПУ ЦЕЛИ (одна железка
 *     против ящера и против человека работает по-разному);
 *   • щит цели вычитается из таблицы «щит против этого оружия», и меньше единицы урон не бывает.
 *
 * Зачем это здесь. Все решения образца — «по зубам ли», «за сколько ударов меня убьют», «опасен
 * ли зверь» — считались по голым характеристикам. Владелец: «в силе врагов и своих юнитов надо
 * учитывать навесное оружие и щиты, они прям очень сильно меняют расстановку». Так и есть:
 * человек с мечом и щитом и он же с голыми руками — это разные бойцы, а расчёт их не различал.
 */
const МАГИЯ_ТАБЛИЦЫ = { 5: [0x37990, 0x379b8], 6: [0x379d7, 0x379ff], 7: [0x37a1e, 0x37a46], 8: [0x37a65, 0x37a8d] };
export function уронПо(m, кто, кого) {
  const б = UNITS + кто, ц = UNITS + кого;
  const тип = m.u8(б + U.TYPE), типЦели = m.u8(ц + U.TYPE);
  let al = урон(m.u8(б + U.ATK), m.u8(ц + U.DEF));
  const магия = МАГИЯ_ТАБЛИЦЫ[тип];
  if (магия) {
    al = (al + m.u8(магия[0] + типЦели)) & 0xff;
    const щ = m.u8(ц + U.SHIELD);
    if (щ !== 0xff) { const v = al - m.u8(магия[1] + щ); al = v < 0 ? 1 : v; }
    return Math.max(1, al);
  }
  let таблица = 0x37b54;                                  // «без оружия»
  const ор = m.u8(б + U.WEAPON);
  if (ор !== 0xff) { const wid = m.u8(б + U.INV + ор); таблица = m.u32(0x37af4 + wid * 4); al = (al + m.u8(типЦели + таблица)) & 0xff; }
  const щ = m.u8(ц + U.SHIELD);
  if (щ !== 0xff) { const cl = m.u8(ц + U.INV + щ); const v = al - m.u8(cl + таблица + 0x28); al = v <= 0 ? 1 : v; }
  return Math.max(1, al);
}

export const жив = (m, i) => !!i && !(m.u8(UNITS + i + U.FLAGS5B) & 1) && m.u8(UNITS + i + U.HP) > 0
                            && (m.u8(UNITS + i + U.STATE) & 0xf0) !== 0x60;
const кл = (m, i) => ({ x: m.u16(UNITS + i + U.X) >> 5, y: m.u16(UNITS + i + U.Y) >> 5 });
const далеко = (a, b) => Math.max(Math.abs(a.x - b.x), Math.abs(a.y - b.y));
/** Точка внутри охотничьих угодий (прямоугольник в клетках). */
const вУгодьях = (у, т) => !у || (т.x >= у.x0 && т.x <= у.x1 && т.y >= у.y0 && т.y <= у.y1);

/**
 * По зубам ли нам эта погоня: успеем ли убить преследователей раньше, чем потеряем первого.
 *
 * Нужно из-за того, что владелец увидел: «они бесконечно начинают бегать от зверей, даже если все
 * оторвались и остался только один зверь, и у них достаточно сил, чтобы его завалить». Так и
 * было — правило усталости («у всех меньше половины жизней») запрещало возвращаться в драку, и
 * отряд убегал от одной гиены до конца времён. Теперь считаем размен честно: сколько тиков нам
 * нужно на их убийство и через сколько тиков погибнет наш слабейший.
 */
/**
 * Преследует ли нас этот зверь ПО-НАСТОЯЩЕМУ.
 *
 * Мало того, что в его поле цели записан кто-то из наших: в опыте «один против трёх»
 * (tools/опыт_погони.mjs) видно, что настоящий преследователь всё время сидит в состояниях
 * 0x30–0x32 (идёт за целью и бьёт), а тот, кто уже потерял интерес, стоит в 0x38 — бродит сам по
 * себе, хотя старая цель у него в поле ещё записана. Владелец на это и жаловался: на экране одна
 * собака, а счётчик показывает три. Считаем преследователем только того, кто в боевом состоянии.
 */
function преследуетНас(m, з, места, свои, поСостоянию = false) {
  const ц = m.u32(UNITS + з + U.TARGET);
  const наш = ТРУП_СЧИТАЕТСЯ ? места.includes(ц) : свои.includes(ц);
  if (!наш) return false;
  if (!поСостоянию) return true;
  // Разбор состояний из самого движка (js/port/move.js, диспетчер 0x18e89):
  //   0x30 бьёт вплотную · 0x31 идёт к цели · 0x32 пауза между ударами · 0x33 начал погоню
  //   0x36/0x37 ИДЁТ ДОМОЙ (в 0x37 берёт свою домашнюю клетку +0x44/+0x45, в 0x36 шагает к ней)
  //   0x38 бродит на месте и высматривает новую цель
  //   0x1x рукопашная схватка
  // Поле цели движок при этом НЕ ЧИСТИТ: уходя домой или бродя, зверь сохраняет старую запись, и
  // читать её как «преследует» нельзя. Настоящее намерение — только боевые состояния.
  const сост = m.u8(UNITS + з + U.STATE);
  return (сост >> 4) === 1 || (сост >= 0x30 && сост <= 0x33);
}

// Во сколько раз строже считать размен из-за размера зверя. Мерка — запас жизней зверя против
// среднего запаса нашего бойца, возведённая в степень основанием ЖИРНЫЙ_РОСТ.
export function жирность(m, свои, звери) {
  if (ЖИРНЫЙ_РОСТ <= 1 || !свои.length || !звери.length) return 1;
  let наш = 0;
  for (const i of свои) наш += m.u8(UNITS + i + U.HPMAX);
  наш /= свои.length;
  if (наш <= 0) return 1;
  let степень = ПОРОГ_ЖИРНОГО;
  for (const з of звери) степень = Math.max(степень, Math.min(ЖИРНЫЙ_ПОТОЛОК, m.u8(UNITS + з + U.HPMAX) / наш));
  return Math.pow(ЖИРНЫЙ_РОСТ, степень - ПОРОГ_ЖИРНОГО);
}

/**
 * САМОВОЛКА: движок сам нашёл бойцу цель, пока мы вели его пешком.
 *
 * Разбор 0x18e89: любой, кто стоит в охране (состояние 0x38), раз в несколько тиков зовёт
 * 0x1a526 — поиск врага по спирали, — и, найдя, уходит в атаку через 0x19fdf. В это состояние
 * наш боец попадает сам собой: как только он доходит до точки, куда мы его послали, приказ
 * кончается и он встаёт в охрану. Дальше зверь подходит в две клетки — и боец кидается на него
 * ПО СВОЕЙ ИНИЦИАТИВЕ. У каждого своя цель, отряд разваливается на четыре отдельных драки.
 * Именно это и видно на экране как «врассыпную»: чем больше мы водим людей пешком (отход,
 * сбор, тыл), тем чаще движок перехватывает управление.
 *
 * Поэтому: пока у бойца есть НАШ маршрут, чужая цель — повод повторить приказ. Приказ идти
 * обнуляет поле цели (applyOrder берёт цель из +0x47, там ноль), и боец возвращается к нам.
 */
const самоволка = (m, i) => m.u32(UNITS + i + U.TARGET) !== 0;

/**
 * МАГ, ОТ КОТОРОГО В ДРАКЕ ТОЛКУ НЕТ.
 *
 * Владелец: «Радумба нападает на тигра, его магия не имеет урона; видимо ты считал силу магов
 * просто по параметру маны, а не по его магическим способностям. Надо исключить эту силу из
 * расчёта для магов без урона и без лечения».
 *
 * Как это устроено в игре. Умения лежат битовой маской в U.SKILLS (+0x17), стоимость и доступность
 * проверяет 0x14873. Лечебные заклинания — биты 8–11 (выбор в pickHeal, magic.js), боевые —
 * 14–17 и 19–22 (перебор в 0x16b47). Урон самого удара мага считает 0x1e758: к базе прибавляется
 * ЕГО таблица по типу цели, и таблицы у видов разные — у т5 и т6 там НУЛИ по всем зверям, то есть
 * «магия» этих двух не добавляет ничего, у т7 всего +3 по зверю, у т8 +2 и только по людям.
 *
 * Поэтому в силу отряда такой маг не идёт вовсе: ни ударом, ни лечением он размен не меняет.
 */
// Считать по списку боевых умений я пробовал — список неполон: у мага Ромака (т8) стоит бит 24,
// которого нет ни в одном разборе выбора заклинаний, а бьёт он при этом нормально. Поэтому меркой
// берём НЕ биты, а сам урон по этой цели, как его считает движок, плюс умение лечить.
const МАГ = (т) => т >= 5 && т <= 8;
const ТИП_КОНСТРУКТОРА = 4;        // им правит слой стройки, в отряде его нет
const ТИП_СКЛАДА = 30;             // мясное хранилище: туда относят добычу
const ВЕЩЬ_МЯСО = 0x1e;            // предмет «мясо» в инвентаре
const УМЕНИЯ_ЛЕЧЕНИЯ = (1 << 8) | (1 << 9) | (1 << 0xa) | (1 << 0xb);   // pickHeal, magic.js
const ЛЕЧИТ = (m, i) => (m.u32(UNITS + i + U.SKILLS) & УМЕНИЯ_ЛЕЧЕНИЯ) !== 0;
/** Маг, который по ЭТОЙ цели не наносит ничего (минимальная единица) и не умеет лечить. */
function пустойМаг(m, i, цель) {
  if (!МАГ(m.u8(UNITS + i + U.TYPE))) return false;
  if (ЛЕЧИТ(m, i)) return false;
  return уронПо(m, i, цель) <= 1;
}

// УЖЕ В БОЮ? Для воина это состояние 0x1x с нашей целью. Для МАГА всё иначе: движок сам выбирает
// заклинание (0x16531) и ставит приказ 0xa0–0xd7, после чего маг живёт в состояниях 0x80–0xdf,
// подходит на дистанцию и колдует. Если в этот момент переотдать «атакуй», приказ заклинания
// слетает — а наш образец делал это КАЖДЫЙ ТИК, потому что проверял только 0x1x. Итог, который
// владелец и видел у Moospell: два мага с полной маной и полным здоровьем стоят столбом всю
// миссию, ни одного удара, а два воина в это время умирают. Считаем мага занятым, пока он колдует.
function занятБоем(m, i, цель) {
  const сост = m.u8(UNITS + i + U.STATE), прик = m.u8(UNITS + i + U.ORDER);
  if (прик >= 0xa0 && прик <= 0xd7) return true;          // приказ-заклинание ещё не применён
  if (сост >= 0x80) return true;                          // заклинание в работе
  return (сост >> 4) === 1 && m.u32(UNITS + i + U.TARGET) === цель;
}

/**
 * ЗАСТРЯЛ НА ПОДХОДЕ. Движок, не найдя пути для удара, оставляет бойца в «иду бить» (0x11) стоять
 * на месте без конца, и повтор того же приказа ничего не меняет. Тирано/2, зерно 6: отряд полторы
 * минуты простоял в проходе над базой, «атакуя» леопарда у загона, пока тот с псом ломали дома;
 * обычный же приказ «идти» в ту же клетку доводил бойца до зверя за три секунды, и там движок
 * сам вступал в драку. Поэтому: стоит в «иду бить» не вплотную ЗАСТРЯЛ_НА_ПОДХОДЕ тиков —
 * возвращаем true, и вызывающий посылает его пешком к цели.
 */
function застрялНаПодходе(m, i, цель) {
  if (!ЗАСТРЯЛ_НА_ПОДХОДЕ) return false;
  const сост = m.u8(UNITS + i + U.STATE);
  if (!((сост >> 4) === 1 && m.u32(UNITS + i + U.TARGET) === цель)) return false;
  if (Math.max(Math.abs(m.u16(UNITS + i + U.X) - m.u16(UNITS + цель + U.X)),
               Math.abs(m.u16(UNITS + i + U.Y) - m.u16(UNITS + цель + U.Y))) <= 48) return false;
  let к = стоятНаПодходе.get(m); if (!к) стоятНаПодходе.set(m, к = new Map());
  const x = m.u16(UNITS + i + U.X), y = m.u16(UNITS + i + U.Y), шаг = m.u32(G.step);
  const б = к.get(i);
  if (!б || б.x !== x || б.y !== y || б.цель !== цель) { к.set(i, { x, y, цель, шаг }); return false; }
  if (шаг - б.шаг < ЗАСТРЯЛ_НА_ПОДХОДЕ) return false;
  к.set(i, { x, y, цель, шаг });
  return true;
}

/** Ближайшая к точке клетка, куда можно прийти: рельеф проходим и нет дома (сетка BI). */
function своднаяКлетка(m, т) {
  if (!СВОБОДНЫЙ_ЦЕНТР) return т;
  for (let r = 0; r <= 4; r++) for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
    if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
    const x = т.x + dx, y = т.y + dy;
    if (проходима(m, x, y) && !(m.u8(BI + x + (y << 8)) & 0xfc)) return { x, y };
  }
  return т;
}

/** Гонец за вещью (см. шагОдного): ведёт одного бойца и возвращает остальных. */
function гонецЗаВещью(eng, m, свои, с) {
  const шаг = m.u32(G.step);
  let г = с.гонец;
  const есть = (i, тип) => { for (let k = 0; k < 12; k++) if (m.u8(UNITS + i + U.INV + k) === тип) return true; return false; };
  if (г && (!жив(m, г.кто) || !свои.includes(г.кто) || шаг > г.до)) г = с.гонец = null;
  if (!г) {
    // Не под погоней: никто из зверья не держит нас целью.
    for (let з = m.u32(G.unitHead); з; з = m.u32(UNITS + з + U.NEXT))
      if (ЗВЕРЬ(m.u8(UNITS + з + U.TYPE)) && жив(m, з) && свои.includes(m.u32(UNITS + з + U.TARGET))) return свои;
    let x = 0, y = 0; for (const i of свои) { const c = кл(m, i); x += c.x; y += c.y; }
    const серед = { x: Math.round(x / свои.length), y: Math.round(y / свои.length) };
    // И только когда вокруг отряда тихо: на старте Тирано/2 леопард с псом стоят рядом, и
    // отделившийся гонец оставлял троих на съедение (трое погибли за 10 секунд).
    for (let з = m.u32(G.unitHead); з; з = m.u32(UNITS + з + U.NEXT))
      if (ЗВЕРЬ(m.u8(UNITS + з + U.TYPE)) && жив(m, з) && далеко(кл(m, з), серед) <= ГОНЕЦ_ТИХО) return свои;
    for (const в of вещиРядом(m, серед, ГОНЕЦ_РАДИУС)) {
      // Берёт тот, кому вещь нужна и у кого больше жизней.
      const кто = свои.filter(i => НОСИТ_ВЕЩИ(m.u8(UNITS + i + U.TYPE)) && естьМесто(m, i, в.оружие)
                                  && (в.оружие ? m.u8(UNITS + i + U.WEAPON) === 0xff : m.u8(UNITS + i + U.SHIELD) === 0xff))
                        .sort((a, b) => m.u8(UNITS + b + U.HP) - m.u8(UNITS + a + U.HP))[0];
      if (!кто) continue;
      г = с.гонец = { кто, тип: в.тип, x: в.x, y: в.y, фаза: 'туда', до: шаг + ГОНЕЦ_СРОК, приказ: -1e9, где: null };
      с.выходы = (с.выходы || {}); с.выходы.гонец = (с.выходы.гонец || 0) + 1;
      break;
    }
    if (!г) return свои;
  }
  const остальные = свои.filter(i => i !== г.кто);
  const c = кл(m, г.кто);
  if (г.фаза === 'туда' && есть(г.кто, г.тип)) г.фаза = 'назад';
  if (г.фаза === 'туда') {
    let лежит = false;
    for (let it = m.u32(0x31b7c), n = 0; it && n < 4096; it = m.u32(ITEMS + it + 0xc), n++)
      if (m.u8(ITEMS + it) === г.тип && m.u8(ITEMS + it + 1) === г.x && m.u8(ITEMS + it + 2) === г.y) { лежит = true; break; }
    if (!лежит) г.фаза = 'назад';
  }
  const стоит = г.где && г.где.x === c.x && г.где.y === c.y;
  if (г.фаза === 'туда') {
    if (шаг - г.приказ > 360 || (стоит && шаг - г.приказ >= ПОВТОРНАЯ_ПОПЫТКА)) {
      приказ(eng, г.кто, КОД.ДОБЫЧА, 0, г.x << 5, г.y << 5); г.приказ = шаг;
    }
  } else {
    let x = 0, y = 0; for (const i of остальные) { const к = кл(m, i); x += к.x; y += к.y; }
    const куда = остальные.length ? { x: Math.round(x / остальные.length), y: Math.round(y / остальные.length) } : c;
    if (далеко(c, куда) <= 3) { с.гонец = null; return свои; }
    if (!г.куда || далеко(г.куда, куда) > 2 || (стоит && шаг - г.приказ >= ПОВТОРНАЯ_ПОПЫТКА)) {
      приказ(eng, г.кто, КОД.ИДТИ, 0, куда.x << 5, куда.y << 5); г.приказ = шаг; г.куда = куда;
    }
  }
  г.где = c;
  return остальные;
}

/** Свободная клетка рядом с целью, ближайшая к бойцу: туда и ведём пешком застрявшего. */
function клеткаУЦели(m, i, цель) {
  const ц = кл(m, цель), я = кл(m, i);
  let лучшая = null, ближе = 1e9;
  for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
    if (!dx && !dy) continue;
    const x = ц.x + dx, y = ц.y + dy;
    if (!проходима(m, x, y) || (m.u8(BI + x + (y << 8)) & 0xfc)) continue;
    const д = далеко({ x, y }, я);
    if (д < ближе) { ближе = д; лучшая = { x, y }; }
  }
  return лучшая;
}

/** Подойти к цели пешком вместо «бить», если застрял. true — приказ отдан или боец ещё идёт. */
function подходПешком(eng, m, i, цель, с) {
  const идёт = (с.подходят ??= new Map()).get(i);
  if (идёт && идёт.цель === цель && m.u32(G.step) < идёт.до
      && далеко(кл(m, i), кл(m, цель)) > 1) return true;
  if (идёт) с.подходят.delete(i);
  if (!застрялНаПодходе(m, i, цель)) return false;
  const т = клеткаУЦели(m, i, цель);
  if (!т) return false;
  приказ(eng, i, КОД.ИДТИ, 0, т.x << 5, т.y << 5);
  с.подходят.set(i, { цель, до: m.u32(G.step) + ПОДХОД_СРОК });
  с.выходы = (с.выходы || {}); с.выходы.подходПешком = (с.выходы.подходПешком || 0) + 1;
  return true;
}
const стоятНаПодходе = new WeakMap();

// НЕ ЗАГОНЯТЬ СЕБЯ В УГОЛ. Владелец: «бывает, зажимают меня в углу, и оттуда уже некуда бежать;
// надо избегать мест, из которых нет выхода; не стоит отходить в точку, где с двух сторон будет
// препятствие; если точка отступления выпала туда — надо взять что-то рядом». Считаем выходы:
// сколько из восьми соседних клеток проходимы. Клетка у стены (5 выходов) ещё терпима, угол и
// карман (3–4) — уже ловушка.
/** Сколько свободных клеток вокруг точки. */
function выходы(m, x, y) {
  let n = 0;
  for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
    if (!dx && !dy) continue;
    if (проходима(m, x + dx, y + dy)) n++;
  }
  return n;
}
/**
 * Точка для отхода: та же, если из неё есть куда деться, иначе ближайшая нормальная рядом.
 * Возвращает null, если и заменить нечем — тогда вызывающий просто не идёт туда.
 */
function неТупик(m, x, y) {
  if (проходима(m, x, y) && выходы(m, x, y) >= ВЫХОДОВ_НАДО) return { x, y };
  let лучшая = null, лучшиеВыходы = -1;
  for (let r = 1; r <= ИСКАТЬ_РЯДОМ; r++) {
    for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
      if (Math.max(Math.abs(dx), Math.abs(dy)) !== r) continue;
      const цx = x + dx, цy = y + dy;
      if (!проходима(m, цx, цy)) continue;
      const в = выходы(m, цx, цy);
      if (в > лучшиеВыходы) { лучшиеВыходы = в; лучшая = { x: цx, y: цy }; }
    }
    if (лучшиеВыходы >= ВЫХОДОВ_НАДО) return лучшая;          // нашли нормальную на этом кольце
  }
  return лучшая;                                              // хоть что-то посвободнее
}

export function поЗубам(m, свои, гонятся, запас = ЗАПАС_РАЗМЕНА, поКаждому = ПО_КАЖДОМУ) {
  if (!гонятся.length || !свои.length) return true;
  // Скорость ударов: человек раз в 8 шагов, ящер и зверь раз в 6 (замер, см. справочник.тиковНаУдар),
  // от скорости не зависит; РАСТЕНИЕ бьёт КАЖДЫЙ ТИК: в
  // 0x18568 оно просто зовёт 0x1ead3 с уроном 1 по найденному рядом (радиус 4 у цветка, 3 у гриба).
  // Единица за тик — это 18 очков в секунду, вчетверо больнее гиены; по формуле скорости выходило
  // 0.06 удара за тик, и цветок в расчёте смотрелся безобиднее собаки.
  const темп = (i) => РАСТЕНИЕ(m.u8(UNITS + i + U.TYPE))
    ? 1 : 1 / тиковНаУдар(m.u8(UNITS + i + U.TYPE));   // ударов за тик
  let нашУрон = 0;
  for (const i of свои) for (const з of гонятся) {
    if (пустойМаг(m, i, з)) continue;                  // его «магия» по этой цели — ноль, в силу не идёт
    нашУрон += уронПо(m, i, з) * темп(i) / гонятся.length;
  }
  let ихЗдоровье = 0;
  for (const з of гонятся) ихЗдоровье += m.u8(UNITS + з + U.HP);
  // РЕГЕНЕРАЦИЯ. Движок раз в шестнадцать тиков добавляет КАЖДОМУ живому по очку здоровья
  // (0x18ab2, вызов при (шаг & 0xf) === 0 из 0x18154 и 0x18e0b). Это 0.0625 очка за тик — мелочь
  // против гиены и решающая величина против тигра: воин Тирано снимает ему по ОДНОМУ очку за
  // удар, вдвоём это 0.14 в тик, и тигр отрастает почти столько же. На записи владельца так и
  // было: двое дерутся с тигром полминуты, его здоровье топчется на 22–25, а наши гибнут.
  // Считаем чистый урон; если он не перекрывает отрастание — цель не убиваема в принципе.
  const РЕГЕН = 1 / 16;
  const чистыйУрон = нашУрон - гонятся.length * РЕГЕН;
  const тиковНаУбийство = чистыйУрон > 0 ? ихЗдоровье / чистыйУрон : 1e9;
  // Их урон считаем НА ВЕСЬ ОТРЯД, а не на одного. Поправка владельца: «не надо в одного урон
  // считать, мы же кайтим, значит урон считать на всю команду». И верно: смена туши размазывает
  // удары по всем, поэтому запас прочности — это суммарное здоровье отряда, а не здоровье
  // слабейшего.
  // Их урон — средний по нашим бойцам: у кого щит, тому достаётся меньше, и это теперь видно.
  let ихУрон = 0;
  for (const з of гонятся) {
    let сумма2 = 0;
    for (const i of свои) сумма2 += уронПо(m, з, i);
    ихУрон += (сумма2 / свои.length) * темп(з);
  }
  // СЧИТАЕМ ПО КАЖДОМУ, А НЕ СУММОЙ. Поправка владельца: «жизней не суммарно надо считать, а по
  // каждому». И правильно: умирает конкретный боец, когда КОНЧАЕТСЯ ЕГО здоровье, а не когда
  // исчерпан общий запас отряда. Сумма льстила: четверо по семь жизней выглядели как двадцать
  // восемь, будто это один крепкий боец, — и отряд лез в драку, из которой не выходил.
  // Берём самого слабого из живых: он погибнет первым, и его смерть — это уже потеря.
  const слабейший = Math.min(...свои.map(i => m.u8(UNITS + i + U.HP)));
  const сумма = свои.reduce((a, i) => a + m.u8(UNITS + i + U.HP), 0);
  // В НАПАДЕНИИ и В БЕГСТВЕ запас считается по-разному, и это не придирка:
  //   нападаем — бой ведём мы, тушу меняем сами, удары размазываются по отряду → берём СУММУ;
  //   убегаем — нас догоняют и бьют в спину того, кто не успел, ротации нет → берём СЛАБЕЙШЕГО.
  // С одной меркой выходило плохо в обе стороны: по сумме отряд Moospell лез на носорога, по
  // слабейшему отряд Тирано не нападал вообще ни на кого и погибал стоя.
  const запасЖизней = поКаждому ? слабейший : сумма;
  // РОТАЦИЯ СБИВАЕТ ИХ УРОН. Когда дерёмся отрядом, битый выходит из-под удара, зверь выбирает
  // новую жертву и идёт к ней — всё это время он не бьёт никого. Владелец именно так тигров и
  // валит руками: «тигра ссут они сильно, хотя вполне могли бы и убить». Прямой расчёт этого не
  // видел и считал тигра сильнее четвёрки. Поэтому в отрядном счёте (сумма) их урон берётся с
  // коэффициентом: КОЭФ_РОТАЦИИ. В счёте по слабейшему (убегаем, ротации нет) поправки нет.
  // Против РАСТЕНИЯ ротация не работает: оно стоит на месте и каждый тик бьёт того, кто ближе, —
  // подставлять вместо битого свежего некому и незачем. Поэтому поправку на смену туши берём
  // только против тех, кто ходит.
  // РОТАЦИЯ ЗАВИСИТ ОТ ЧИСЛА БОЙЦОВ. Вчетвером битого и правда есть кем подменить, вдвоём —
  // почти нет, а один не меняется вовсе. Раньше коэффициент был один на любой отряд, и двойка
  // простолюдинов по расчёту выходила неуязвимой для леопарда.
  const подмена = Math.min(1, Math.max(0, свои.length - 1) / 3);          // 1 боец → 0, четверо → 1
  // РОТАЦИЯ НЕ УСПЕВАЕТ, если зверь убивает бойца быстрее, чем тот выйдет из-под удара. Мамонт
  // Тирано/2 бьёт простолюдина по 5 раз в 8 тиков и кладёт его за 48 тиков — подменять некого, и
  // с поправкой на ротацию четвёрка «побеждала» его в расчёте, а на деле гибла вся (зерно 9).
  // Опыт, по умолчанию выключен: РЕАКЦИЯ — сколько тиков нужно битому, чтобы уйти.
  let успеваем = true;
  // Только для ЖИРНЫХ (крупнее ПОРОГ_ЖИРНОГО наших): леопарда и пса правило не трогает — с ним
  // на пробе отряд переставал защищать дома от них, и база падала на первой минуте.
  if (РЕАКЦИЯ > 0) for (const з of гонятся) {
    if (жирность(m, свои, [з]) <= 1) continue;
    let самыйСильный = 0;
    for (const i of свои) самыйСильный = Math.max(самыйСильный, уронПо(m, з, i) * темп(з));
    if (самыйСильный > 0 && слабейший / самыйСильный < РЕАКЦИЯ) успеваем = false;
  }
  const ротация = (поКаждому || !успеваем || гонятся.some(з => РАСТЕНИЕ(m.u8(UNITS + з + U.TYPE))))
    ? 1 : (1 - (1 - КОЭФ_РОТАЦИИ) * подмена);
  // Мы тоже отрастаем — но ЗАЛЕЧИВАЕТ УДАРЫ ТОЛЬКО ТОТ, ПО КОМУ БЬЮТ. Раньше здесь вычиталась
  // регенерация ВСЕГО отряда, и выходила чепуха: двое простолюдинов «отрастали» 0.125 за тик, а
  // леопард бил на 0.1 — по расчёту он не мог их убить вовсе, и отряд лез в драку, которая
  // тянулась минутами и кончалась похоронами. Владелец это и увидел: «они не могут добить гиену
  // никогда… что-то с коэффициентами не так». Зверь бьёт одного, значит и лечится один.
  // Регенерация не может обнулить урон совсем: удары всё равно копятся быстрее, чем лечение
  // успевает их залечивать (на деле лечение идёт равномерно, а удары — сериями). Поэтому у
  // чистого урона есть пол: пятая часть от сырого.
  const ихЧистый = Math.max(ихУрон * ротация - РЕГЕН, ихУрон * ПОЛ_УРОНА);
  const тиковДоСмерти = ихЧистый > 0 ? запасЖизней / ихЧистый : 1e9;
  // Поправка на ЖИРНОСТЬ (см. ЖИРНЫЙ_РОСТ). Чем крупнее зверь по сравнению с нашим бойцом, тем
  // больший перевес нужен, чтобы вообще с ним связываться, — и растёт требование геометрически,
  // а не сложением. Берём самого крупного из набора: связавшись с мамонтом, дерёшься с мамонтом.
  return тиковНаУбийство * запас * жирность(m, свои, гонятся) < тиковДоСмерти;
}

/**
 * Спокойно ли: НАС НИКТО НЕ ПРЕСЛЕДУЕТ и ближайший зверь не дышит в затылок.
 *
 * Раньше сюда шло число «агров», а оно считает и тех, кто просто стоит в двух клетках и на нас не
 * смотрит. Из-за этого отряд, от которого зверь уже отстал, всё равно не считался свободным и
 * бегал дальше. Владелец: «когда зверь уже не преследует, они продолжают бегать, а надо просто
 * встать поспать, дождаться, когда все полностью восстановятся, и снова идти».
 */
const спокойно = (гонящихся, доБлижайшего) => гонящихся === 0 && доБлижайшего > ОТОРВАЛИСЬ;

/**
 * Мясо на земле: что выпало с убитых. Проверено замером — с гиены падает предмет типа 30 примерно
 * на 200 единиц, и куча медленно тает сама (200 → 196 за полминуты), так что забирать её надо.
 *
 * Зачем вообще: ноша бойца расходуется сама собой (30 → 21 за сорок секунд), а на нуле юнит
 * перестаёт восстанавливать здоровье. Владелец: «убили, забрали мясо; сейчас юниты просто
 * перестают восстанавливаться от того, что мясо кончается».
 */
function мясоРядом(m, откуда, радиус) {
  const с = [];
  for (let i = m.u32(0x31b7c); i; i = m.u32(ITEMS + i + 0xc)) {
    if (m.u8(ITEMS + i) !== ТИП_МЯСА) continue;
    const x = m.u8(ITEMS + i + 1), y = m.u8(ITEMS + i + 2);
    const д = далеко({ x, y }, откуда);
    if (д <= радиус) с.push({ i, x, y, д, кол: m.u16(ITEMS + i + 6) });
  }
  return с.sort((a, b) => a.д - b.д);
}

/**
 * Чужие ПЛЕМЕНА (не зверьё): люди, маги, ручные динозавры другого владельца.
 *
 * Правило владельца: «есть драка масаев — там сразу другой компьютер дерётся, там человек с щитом,
 * которого невозможно победить, и в целом драка, которую нельзя выиграть, и там не звери враги.
 * Значит надо сразу группой оттуда убегать, даже не вступать в драку». Так и делаем: чужие бойцы
 * не добыча ни при каких условиях, а их близость — сама по себе повод уходить, без расчёта
 * размена. Зверьё определяется типом (14–23), поэтому «не зверь и не наш» — это чужое племя.
 */
function чужиеПлемена(m, мой) {
  const с = [];
  for (let i = m.u32(G.unitHead); i; i = m.u32(UNITS + i + U.NEXT)) {
    if (!жив(m, i)) continue;
    const т = m.u8(UNITS + i + U.TYPE);
    if (т >= 0x1a || ЗВЕРЬ(т) || РАСТЕНИЕ(т)) continue;      // здания, зверьё и растения — не сюда
    if (m.u8(UNITS + i + U.OWNER) === мой) continue;
    с.push(i);
  }
  return с;
}

// ---------------------------------------------------------------- оружие и щиты
//
// Правила владельца целиком: «оружие и щиты надо чтобы подбирали только люди-воины и мускулистые;
// подбирать должны те, у кого в руках ничего нет; по приоритету сначала делаем полноценно
// вооружённого юнита — чтобы был и щит, и меч: если есть хоть что-то, сразу даём ему другое».
//
// Что известно про вещи из самой игры (таблица статов 0x30954/0x30a9e): типы 1–8 — оружие (атака
// от 28 у первого до 2 у восьмого), тип 10 — щит (защита 15), остальное носить смысла нет.
// Инвентарь у юнита: ячейки 0–2 под оружие, 3–5 под щиты; поля +0x4d/+0x4e хранят НОМЕР надетой
// ячейки (0xff — пусто). Надеть — приказ 0xe1 с номером ячейки.
const СТАТ = (m, id, поле) => m.u8(0x30954 + m.u32(0x30a9e + id * 4) + поле);
const АТК_ВЕЩИ = 3, ЗАЩ_ВЕЩИ = 4;
// Оружие и щит различаем по СПИСКУ ВЕЩЕЙ, а не по полю «защита»: у деревянного щита защита нулевая,
// он снимает урон через таблицу оружия нападающего, и прежняя проверка считала его оружием.
const ОРУЖИЕ_ЛИ = (m, id) => группаВещи(id) === 'оружие';
const ЩИТ_ЛИ = (m, id) => группаВещи(id) === 'щит';
/** Носит ли этот юнит оружие и щиты. Люди-бойцы (пещерный, воин, охотник) — да; маги и ящеры — нет. */
const НОСИТ_ВЕЩИ = (т) => т >= 1 && т <= 3;

/** Вещи на земле рядом: оружие и щиты (мясо и прочее сюда не попадает). */
function вещиРядом(m, откуда, радиус, всё = false) {
  const с = [];
  for (let i = m.u32(0x31b7c); i; i = m.u32(ITEMS + i + 0xc)) {
    const тип = m.u8(ITEMS + i);
    // всё=true — и прочее: бананы, травы, женьшень, артефакты (1..29; мясо 0x1e идёт своей веткой)
    const прочее = !ОРУЖИЕ_ЛИ(m, тип) && !ЩИТ_ЛИ(m, тип);
    if (прочее && !(всё && тип >= 1 && тип < 0x1e)) continue;
    const x = m.u8(ITEMS + i + 1), y = m.u8(ITEMS + i + 2);
    const д = далеко({ x, y }, откуда);
    if (д <= радиус) с.push({ i, x, y, д, тип, оружие: ОРУЖИЕ_ЛИ(m, тип), прочее });
  }
  return с.sort((a, b) => a.д - b.д);
}

/**
 * Надеть лучшее из того, что уже в карманах. Оружие выбирается по атаке, щит по защите; если в
 * руках уже лучшее — ничего не делаем (лишний приказ сбрасывает замах).
 */
/**
 * СТРЕЛКОВОЕ ИЛИ РУКОПАШНОЕ. В движке дальность людям дают ровно четыре вещи: предмет 4 (короткий
 * выстрел, act.js: RNG[spd>>6]) и предметы 5–7 (дальний, RNG[spd>>5]). Всё прочее — рукопашное.
 * Владелец: «не переключаться между лучником и рукопашником; если мы качаем рукопашника, то и
 * оружие ему рукопашное даём; однако пока мы не выдали оружие, юнита не обозначаем никем — он
 * может кем угодно стать».
 */
const СТРЕЛКОВОЕ = (id) => id >= 4 && id <= 7;
const КЛАСС_ВЕЩИ = (id) => СТРЕЛКОВОЕ(id) ? 'стрелок' : 'рукопашник';

/** Кем уже «обозначен» боец: по надетому оружию, иначе по памяти, иначе никем. */
function классБойца(m, i, с) {
  const w = m.u8(UNITS + i + U.WEAPON);
  if (w !== 0xff) {
    const id = m.u8(UNITS + i + U.INV + w);
    if (id) { const к = КЛАСС_ВЕЩИ(id); (с.классы ??= new Map()).set(i, к); return к; }
  }
  return с.классы?.get(i) || null;
}

/**
 * Надеть лучшее из того, что в карманах. Всегда переключаемся на лучшее — но ТОЛЬКО В СВОЁМ
 * классе: лучник не берёт дубину, рукопашник не берёт лук. Пока класса нет, берём лучшее вообще —
 * этим выбором боец и определяется.
 */
function надетьЛучшее(eng, i, с = {}) {
  const m = eng.m;
  if (!НОСИТ_ВЕЩИ(m.u8(UNITS + i + U.TYPE))) return false;
  const класс = классБойца(m, i, с);
  for (const [первый, поле, поляСтат, оружие] of [[0, U.WEAPON, АТК_ВЕЩИ, true], [3, U.SHIELD, ЗАЩ_ВЕЩИ, false]]) {
    const надет = m.u8(UNITS + i + поле);
    let лучший = -1, лучшая = надет === 0xff ? 0 : СТАТ(m, m.u8(UNITS + i + U.INV + надет), поляСтат);
    for (let k = первый; k < первый + 3; k++) {
      const id = m.u8(UNITS + i + U.INV + k); if (!id) continue;
      if (оружие && класс && КЛАСС_ВЕЩИ(id) !== класс) continue;     // чужой класс — не трогаем
      const v = СТАТ(m, id, поляСтат);
      if (v > лучшая) { лучшая = v; лучший = k; }
    }
    if (лучший >= 0) {
      if (оружие) (с.классы ??= new Map()).set(i, КЛАСС_ВЕЩИ(m.u8(UNITS + i + U.INV + лучший)));
      приказ(eng, i, КОД.ПАНЕЛЬ, лучший, 0, 0);
      return true;
    }
  }
  return false;
}

/**
 * ЛИШНЕЕ ОРУЖИЕ — ТОВАРИЩУ. Владелец: «скрипт должен следить, чтобы не было оружия лишнего ни у
 * кого: подобрал оружие, не может надеть — пошёл передал тому, у кого ничего нет».
 *
 * Лишнее — это ненадетая вещь, которая владельцу не пригодится: либо чужого класса (лучнику дубина),
 * либо слабее того, что на нём уже надето. Отдаём безоружному, у которого класс либо ещё не
 * определён, либо совпадает с классом вещи. Приказ тот же, что на разгрузку мяса (0x51+слот), только
 * целью стоит человек, а не склад: движок сам доводит и перекладывает (economy.js, 0x19229).
 */
function раздатьЛишнее(eng, свои, с) {
  const m = eng.m;
  const ждать = с.отдают ??= new Map();
  let отдано = 0;
  for (const i of свои) {
    if (!НОСИТ_ВЕЩИ(m.u8(UNITS + i + U.TYPE))) continue;
    const п = ждать.get(i);
    if (п && m.u32(G.step) - п < ОТДАЧА_СРОК) { отдано++; continue; }
    const мойКласс = классБойца(m, i, с);
    const надето = m.u8(UNITS + i + U.WEAPON);
    const силаНадетого = надето === 0xff ? 0 : СТАТ(m, m.u8(UNITS + i + U.INV + надето), АТК_ВЕЩИ);
    for (let k = 0; k < 3; k++) {
      if (k === надето) continue;
      const id = m.u8(UNITS + i + U.INV + k); if (!id) continue;
      const чужогоКласса = мойКласс && КЛАСС_ВЕЩИ(id) !== мойКласс;
      const слабее = СТАТ(m, id, АТК_ВЕЩИ) <= силаНадетого && силаНадетого > 0;
      if (!чужогоКласса && !слабее) continue;                      // вещь ему самому пригодится
      // Кому: безоружному, чей класс подходит (или ещё не определён). Ближайшему.
      let кому = 0, ближе = 1e9;
      for (const j of свои) {
        if (j === i || !жив(m, j) || !НОСИТ_ВЕЩИ(m.u8(UNITS + j + U.TYPE))) continue;
        if (m.u8(UNITS + j + U.WEAPON) !== 0xff) continue;          // он уже вооружён
        const егоКласс = классБойца(m, j, с);
        if (егоКласс && егоКласс !== КЛАСС_ВЕЩИ(id)) continue;
        if (!естьМесто(m, j, true)) continue;
        const д = далеко(кл(m, i), кл(m, j));
        if (д < ближе) { ближе = д; кому = j; }
      }
      if (!кому) continue;
      приказ(eng, i, 0x51 + k, кому, m.u16(UNITS + кому + U.X), m.u16(UNITS + кому + U.Y));
      ждать.set(i, m.u32(G.step));
      отдано++;
      break;
    }
  }
  return отдано;
}

/** Сколько свободных ячеек нужного рода у бойца (0–2 оружие, 3–5 щиты). */
function естьМесто(m, i, оружие) {
  const первый = оружие ? 0 : 3;
  for (let k = первый; k < первый + 3; k++) if (!m.u8(UNITS + i + U.INV + k)) return true;
  return false;
}

/** Живые ядовитые растения на карте. */
function растения(m) {
  const с = [];
  for (let i = m.u32(G.unitHead); i; i = m.u32(UNITS + i + U.NEXT))
    if (жив(m, i) && РАСТЕНИЕ(m.u8(UNITS + i + U.TYPE))) с.push({ ...кл(m, i), н: i });   // н — чтобы можно было взять в цель
  return с;
}
/**
 * ОБХОД ОПАСНОГО УЧАСТКА СВОИМИ ТОЧКАМИ.
 *
 * Беда, которую заметил владелец: «мы хотим атаковать зверя, а на пути опасное препятствие, и у
 * нас поиск пути идёт через него — встрянем и ничего не сможем». Поиск пути в движке чужой, менять
 * его нельзя: он ведёт кратчайшим путём и про ядовитые цветы ничего не знает — для него это
 * обычная проходимая трава.
 *
 * Выход ровно тот, который предложил владелец: не отдавать «иди к зверю» через всю карту, а вести
 * СВОИМИ ПРОМЕЖУТОЧНЫМИ ТОЧКАМИ. Движок честно проложит путь до КАЖДОЙ такой точки, а выбираем их
 * мы — так, чтобы отрезок до неё не задевал опасный круг.
 *
 * `путьЧист` проверяет прямой отрезок по клеткам; `обход` ищет точку в стороне: пробуем отклонения
 * поперёк направления, сперва небольшие, потом всё шире, и берём первую, до которой чисто и от
 * которой видна цель.
 */
function путьЧист(m, откуда, куда, круги) {
  if (!круги.length) return true;
  const dx = куда.x - откуда.x, dy = куда.y - откуда.y;
  const шагов = Math.max(1, Math.round(Math.hypot(dx, dy)));
  for (let ш = 0; ш <= шагов; ш++) {
    const x = Math.round(откуда.x + dx * ш / шагов), y = Math.round(откуда.y + dy * ш / шагов);
    if (ядовито(круги, { x, y })) return false;
  }
  return true;
}

/** Промежуточная точка в обход опасного: null — обходить не надо, undefined — не нашли. */
function обход(m, откуда, куда, круги) {
  if (путьЧист(m, откуда, куда, круги)) return null;
  const dx = куда.x - откуда.x, dy = куда.y - откуда.y, д = Math.hypot(dx, dy) || 1;
  const нx = -dy / д, нy = dx / д;                       // единичная нормаль к направлению
  for (const вбок of [3, 5, 7, 9, 11]) {
    for (const знак of [1, -1]) {
      for (const доля of [0.5, 0.35, 0.7]) {
        const x = Math.round(откуда.x + dx * доля + нx * знак * вбок);
        const y = Math.round(откуда.y + dy * доля + нy * знак * вбок);
        if (!проходима(m, x, y) || ядовито(круги, { x, y })) continue;
        if (!путьЧист(m, откуда, { x, y }, круги)) continue;
        return { x, y };
      }
    }
  }
  return undefined;
}

/** Точка в запретном круге растения? */
const ядовито = (точки, т) => точки.some(р => далеко(р, т) <= КРУГ_РАСТЕНИЯ);

/** Все живые звери на карте (их немного, перебор дешёвый). */
function всеЗвери(m) {
  const с = [];
  for (let i = m.u32(G.unitHead); i; i = m.u32(UNITS + i + U.NEXT))
    if (жив(m, i) && ЗВЕРЬ(m.u8(UNITS + i + U.TYPE))) с.push(i);
  return с;
}

/**
 * Куда бежать: прямой отрезок от середины отряда, в конце которого дальше всего до зверья.
 *
 * Оценка по КОНЕЧНОЙ ТОЧКЕ, а не по пути: преследователь бежит сзади, и если считать по пути,
 * любое направление выглядит одинаково плохо. Длина отрезка ограничена проходимостью (луч), и
 * слишком короткие отрезки отбрасываем — рывок в три клетки ничего не даёт, а именно прямая
 * дорога позволяет оторваться.
 */
function кудаОтрываться(m, серед, звери, гонятся = [], курс = null, сторона = 1, свои = [], ядовитые = [], желание = null) {
  // ПРИОРИТЕТ НАПРАВЛЕНИЯ. Владелец: «если у нас желание идти и атаковать зверя вдалеке, а между
  // нами мамонт, то когда мамонт на нас агрится, отступать лучше в сторону нашей цели
  // изначальной. Однако это должен быть лишь приоритет: если мамонт зажимает нас в угол, это уже
  // ниже приоритет». Поэтому — прибавка к оценке направления (косинус угла к цели), меньшая, чем
  // штрафы за тупик и за проход мимо опасного.
  const уголЖелания = желание ? Math.atan2(желание.y - серед.y, желание.x - серед.x) : null;
  const точки = звери.map(з => кл(m, з));
  // ОПАСНЫЕ — те, чей удар по нам тяжелее ОПАСНЫЙ_УДАР: тигр снимает по 5 из 30 и бегает втрое
  // быстрее нас. Правило владельца: «надо ещё постараться мимо тигров не бегать — они агрятся,
  // и хрен убежишь от них». Мимо гиены пробежать можно, мимо тигра — нельзя, поэтому штрафуется
  // не всякое зверьё на пути (это я мерил, только вредит), а именно опасное.
  let средняяЗащита = 30;
  if (свои.length) { let с2 = 0; for (const i of свои) с2 += m.u8(UNITS + i + U.DEF); средняяЗащита = Math.round(с2 / свои.length); }
  // Опасный — тот, чей удар по нам тяжёл. Сюда попадают и тигры, и чужие бойцы с оружием:
  // мимо них тропу прокладывать нельзя.
  const опасные = звери.filter(з => (свои.length ? уронПо(m, з, свои[0]) : урон(m.u8(UNITS + з + U.ATK), средняяЗащита)) >= ОПАСНЫЙ_УДАР).map(з => кл(m, з));
  // НЕ БЕЖАТЬ СКВОЗЬ ТОГО, КТО НАПАЛ. Правило владельца: «не должен быть путь отступления обратно
  // через нападающего зверя, надо смещать угол». Поэтому направления на преследователей
  // отбрасываются целиком, а не штрафуются: мягкий штраф я мерил, он не помогал. Берём угол на
  // каждого, кто нас держит, и выкидываем сектор ±СЕКТОР_ГОНЯЩЕГОСЯ вокруг него.
  const углыПогони = гонятся.map(з => { const т = кл(m, з); return Math.atan2(т.y - серед.y, т.x - серед.x); });
  const вСекторе = (угол, предел) => углыПогони.some(у => {
    let d = Math.abs(угол - у) % (2 * Math.PI);
    if (d > Math.PI) d = 2 * Math.PI - d;
    return d < предел;
  });
  // Сперва ищем, отбрасывая сектор погони целиком; если так не нашлось ни одного направления —
  // сужаем запрет вдвое, и лишь потом разрешаем всё (иначе в тесноте отряд встанет столбом).
  for (const предел of [СЕКТОР_ГОНЯЩЕГОСЯ, СЕКТОР_ГОНЯЩЕГОСЯ / 2, 0]) {
  let лучшая = null;
  for (let к = 0; к < СТОРОН; к++) {
    const угол = к * 2 * Math.PI / СТОРОН;
    if (предел > 0 && вСекторе(угол, предел)) continue;
    // БЕЖИМ ПО КРУГУ, А НЕ ВЗАД-ВПЕРЁД. Правило владельца: «по кругу, по квадрату бегать, но не
    // обратно». Разворот назад — это бег навстречу погоне, поэтому он запрещён совсем, а из
    // оставшегося предпочитаем поворот в ОДНУ И ТУ ЖЕ сторону примерно на четверть круга: так
    // отряд обходит поляну квадратом, а не мечется.
    let поворот = 0;
    if (курс !== null) {
      let d = угол - курс;
      while (d > Math.PI) d -= 2 * Math.PI;
      while (d < -Math.PI) d += 2 * Math.PI;
      if (Math.abs(d) > МАКС_ПОВОРОТ) continue;                 // назад не разворачиваемся
      поворот = Math.cos(d - сторона * Math.PI / 2) * ВЕС_КРУГА;  // чем ближе к своей четверти, тем лучше
    }
    const dx = Math.cos(угол), dy = Math.sin(угол);
    // Длину свободного пробега меряем общим `луч` — он ходит по восьми направлениям (знак dx/dy),
    // а точка считается по истинному углу. Расхождение выглядит как ошибка, и я его «исправил»:
    // прошёл настоящую линию клетка за клеткой. Замер (5 вариаций сцены, 90 секунд) сказал
    // обратное — потерь стало 7–9 вместо 3. Причина в том, что строгая проверка отбрасывает
    // почти все наклонные направления (стоит дереву задеть линию — кандидат вылетает), и отряду
    // остаются четыре стороны света. Оставляем как есть: грубая оценка направления тут полезнее
    // точной, дорогу всё равно ищет сам движок.
    const можно = луч(m, Math.round(серед.x), Math.round(серед.y), Math.sign(dx) || 0, Math.sign(dy) || 0, ОТРЕЗОК);
    const шагов = Math.min(ОТРЕЗОК, можно);
    if (шагов < 4) continue;
    // Конец отрезка тоже не должен быть углом: бежать в карман — значит дать себя там зажать.
    const конец = неТупик(m, Math.round(серед.x + dx * шагов), Math.round(серед.y + dy * шагов));
    if (!конец) continue;
    const x = конец.x, y = конец.y;
    if (ядовито(ядовитые, { x, y })) continue;
    // Бежать в зону зверя-убийцы нельзя: это выпас мамонта или тигра плюс радиус его нападения.
    if (ОТРЫВ_МИМО_ЗОН && зоныУбийц.some(в => x >= в.x0 && x <= в.x1 && y >= в.y0 && y <= в.y1)) continue;
    let доКонца = 1e9;
    for (const т of точки) { const д = далеко(т, { x, y }); if (д < доКонца) доКонца = д; }
    // ПУТЬ ВАЖНЕЕ КОНЦА. Сперва оценивался только конец отрезка — и отряд бежал по прямой СКВОЗЬ
    // тех, кто его кусает: зверь не отставал ни на шаг, потому что мы сами шли ему навстречу.
    // Владелец: «у них есть место, куда лучше отойти, но они упорно бегают прямо через атакующих
    // зверей; они могли бы чуть выше подняться и от тигра отбегать». Поэтому проходим отрезок
    // шагами и штрафуем за каждое сближение со зверем по дороге: чем ближе тропа проходит к
    // пасти, тем дороже. Штраф квадратичный — задеть впритык гораздо хуже, чем пройти в трёх
    // клетках.
    // Штрафуем НАЧАЛО пути, а не весь отрезок. Замер (5 вариаций сцены): штраф по всей длине
    // только вредит — 5 потерь против 3, — потому что преследователь всё равно бежит сзади и
    // «портит» любое направление. А вот первые клетки решают: именно там отряд либо обходит
    // кусающего, либо лезет ему в пасть.
    let штраф = 0;
    const досюда = Math.min(шагов, ПЕРВЫХ_ШАГОВ);
    for (let ш = 1; ш <= досюда; ш++) {
      const тx = Math.round(серед.x + dx * ш), тy = Math.round(серед.y + dy * ш);
      let ближе = 1e9;
      for (const т of точки) { const д = далеко(т, { x: тx, y: тy }); if (д < ближе) ближе = д; }
      if (ближе < ОПАСНО) { const п = (ОПАСНО - ближе); штраф += п * п; }
    }
    // Отдельно и куда строже — проход рядом с опасным зверем, по всей длине отрезка.
    let штрафОпасных = 0;
    for (let ш = 1; ш <= шагов; ш++) {
      const тx = Math.round(серед.x + dx * ш), тy = Math.round(серед.y + dy * ш);
      for (const т of опасные) {
        const д = далеко(т, { x: тx, y: тy });
        if (д < КРУГ_ОПАСНОГО) { const п = (КРУГ_ОПАСНОГО - д); штрафОпасных += п * п; }
      }
    }
    // ТУПИК. Владелец: «они стали зажаты справа в мелком проходе, и из-за тигров не могут выйти,
    // их обратно загоняют туда». Отступление выбирало самую дальнюю от зверья точку, а что она в
    // кармане — не проверяло. Считаем, сколько свободных направлений из этой точки: из угла или
    // прохода их два-три, с открытой поляны — почти все.
    let выходов = 0;
    for (let к2 = 0; к2 < 8; к2++) {
      const у2 = к2 * Math.PI / 4;
      if (луч(m, x, y, Math.sign(Math.cos(у2)) || 0, Math.sign(Math.sin(у2)) || 0, 3) >= 3) выходов++;
    }
    const тупик = Math.max(0, СВОБОДНЫХ_НАДО - выходов);
    // НЕ УХОДИТЬ В КУЧУ ПОБОЛЬШЕ. Владелец: «сагрились много зверей — не надо уходить в ещё
    // большую кучу зверей». Оценка смотрела на расстояние до БЛИЖАЙШЕГО зверя, и точка в двух
    // шагах от стада из шести выглядела не хуже пустой поляны. Считаем, сколько зверья вокруг
    // самой точки, и штрафуем за каждого.
    let кучаТам = 0;
    for (const т of точки) if (далеко(т, { x, y }) <= КРУГ_КУЧИ) кучаТам++;
    const оценка = доКонца + шагов * 0.25 - штраф * ВЕС_ТРОПЫ - штрафОпасных * ВЕС_ОПАСНЫХ
                 - тупик * ВЕС_ТУПИКА - кучаТам * ВЕС_КУЧИ + поворот
                 + (уголЖелания !== null ? Math.cos(угол - уголЖелания) * К_ЦЕЛИ : 0);
    if (!лучшая || оценка > лучшая.оценка) лучшая = { x, y, оценка, шагов, штраф, угол };
  }
  if (лучшая) return лучшая;
  }
  return null;
}

/**
 * СПРАВИМСЯ ЛИ С РАСТЕНИЕМ. Владелец: «цветок всё-таки нельзя бить, если победы точно не будет: а
 * это либо минимум 4 человека одновременно самых слабых, либо уже прокачанные бойцы, у которых
 * достаточно жизней; но тоже не по одному, надо минимум вдвоём».
 *
 * Считаем по замерам, а не на глаз:
 *   • наш урон в секунду — сумма по бойцам: урон за удар (таблицы движка) × темп ударов;
 *   • растение лечится, как все: −1 жизнь за 16 тиков из нашего урона;
 *   • растение бьёт КАЖДОГО, кто стоит в круге, примерно на УРОН_ЦВЕТКА жизней в секунду
 *     (прямой замер: четвёрка RaDumBa теряла по 9 жизней в секунду каждый, стоя рядом);
 *   • время = жизни растения / чистый урон, плата = время × УРОН_ЦВЕТКА × число бойцов.
 * Идём, если плата меньше ДОЛЯ_ПОТЕРЬ от суммарных жизней отряда и бойцов не меньше МИН_НА_ЦВЕТОК.
 *
 * Проверка сходится с обоими замерами: четвёрка Moospell (урон 1 каждый) цветок на 55 жизней НЕ
 * берёт — ей нужно 15 секунд и 540 жизней, а есть 120; четвёрка RaDumBa (урон 5–6) берёт его за
 * полторы секунды, теряя полсотни на всех.
 */
function справимсяСЦветком(m, свои, цель) {
  if (свои.length < МИН_НА_ЦВЕТОК) return false;
  let уронВСек = 0, жизни = 0;
  for (const i of свои) {
    const скорость = m.u8(UNITS + i + U.SPD);
    уронВСек += уронПо(m, i, цель) * (1 / тиковНаУдар(m.u8(UNITS + i + U.TYPE)) / 0.055);
    жизни += m.u8(UNITS + i + U.HP);
  }
  const чистый = уронВСек - РЕГЕН_В_СЕК;                   // движок лечит всех: +1 жизнь за 16 тиков
  if (чистый <= 0.2) return false;
  const время = m.u8(UNITS + цель + U.HP) / чистый;
  const заплатим = время * УРОН_ЦВЕТКА * свои.length;
  return заплатим <= жизни * ДОЛЯ_ПОТЕРЬ;
}

/**
 * ХВАТИТ ЛИ УРОНА БЕЗ ЭТОГО БОЙЦА. Владелец прислал Moospell: «они не могут добить гиену никогда,
 * начинают кайтить, но урона не хватает».
 *
 * Причина считается на пальцах. Движок лечит всех на +1 жизнь каждые 16 тиков, то есть примерно
 * 1.1 в секунду. Простолюдин бьёт гиену на 1 раз в 0.83 с — это 1.2 урона в секунду. Вдвоём 2.4,
 * и зверь тает; но стоит одному отойти «подлечиться», как остаётся 1.2 против 1.1 регенерации —
 * и здоровье жертвы стоит на месте. Отряд бегает кругами, зверь не умирает, время уходит.
 *
 * Поэтому личный отход теперь спрашивает: останется ли БЕЗ МЕНЯ урона больше, чем зверь себе
 * отлечивает. Если нет — отход отменяется: добить выгоднее, чем кайтить.
 */
function хватитУронаБезМеня(m, свои, цель, кто, запасКлеток = 1, нуженКонтакт = false) {
  if (!жив(m, цель)) return true;
  const ц = кл(m, цель);
  let уронВСек = 0, вКонтакте = 0;
  for (const i of свои) {
    if (!жив(m, i)) continue;
    const д = далеко(кл(m, i), ц), достаёт = Math.max(1, дальность(m, i));
    if (д <= достаёт) вКонтакте++;
    if (i === кто) continue;                             // его как раз и хотим увести
    if (д > достаёт + запасКлеток) continue;             // слишком далеко, чтобы считаться бойцом
    уронВСек += уронПо(m, i, цель) * (1 / тиковНаУдар(m.u8(UNITS + i + U.TYPE)) / 0.055);
  }
  // Для приговора «не пробиваем» нужен контакт: пока до жертвы никто не дошёл, судить не о чем.
  if (нуженКонтакт && !вКонтакте) return true;
  return уронВСек > РЕГЕН_В_СЕК * ЗАПАС_НА_ДОБИВ;
}

/**
 * ЗА СКОЛЬКО СЕКУНД ЗВЕРЬ УБЬЁТ НАШЕГО САМОГО СЛАБОГО. Урон за удар — таблицами движка (уронПо),
 * темп — удар раз в 6 шагов у зверя (справочник.тиковНаУдар), лечение +1 за 16 тиков. Нужна, чтобы круг «не брать
 * добычу рядом с непосильным» зависел от того, насколько тот опасен: мамонт на высшей сложности
 * убивает простолюдина за три секунды, и двух клеток запаса от него — ничто (замер второй миссии
 * Тирано: двое из четырёх погибли от мамонтов, пока отряд бил леопардов рядом с ними).
 */
function секундДоУбийства(m, з, свои) {
  let худшее = Infinity;
  const темп = 1 / тиковНаУдар(m.u8(UNITS + з + U.TYPE)) / 0.055;
  for (const i of свои) {
    const вСек = уронПо(m, з, i) * темп - РЕГЕН_В_СЕК;
    if (вСек > 0) худшее = Math.min(худшее, m.u8(UNITS + i + U.HP) / вСек);
  }
  return худшее;
}
/** Зоны зверей-убийц на текущем шаге: их видит и выбор цели, и выбор точки отрыва. */
let зоныУбийц = [];
/** Круг вокруг непосильного зверя, где добычу не берём: чем быстрее убивает, тем шире. */
const кругОпасного = (m, з, свои) => {
  const с = секундДоУбийства(m, з, свои);
  return КРУГ_НЕПОСИЛЬНОГО + (с <= 5 ? 4 : с <= 10 ? 2 : 0);
};

/** Сколько живого зверья в радиусе `r` от точки. Мера «гущи»: и для выбора добычи, и для отхода. */
function густо(m, точка, звери, r) {
  let n = 0;
  for (const з of звери) if (далеко(кл(m, з), точка) <= r) n++;
  return n;
}

/** Кто сейчас бьёт этого бойца: список зверей, у которых он назначен целью. */
function ктоБьёт(m, боец, мой) {
  const б = [];
  for (let i = m.u32(G.unitHead); i; i = m.u32(UNITS + i + U.NEXT)) {
    if (!жив(m, i)) continue;
    const т = m.u8(UNITS + i + U.TYPE);
    // Бить нас может и зверь, и чужой боец: для отхода разницы нет, больно одинаково.
    if (т >= 0x1a || РАСТЕНИЕ(т)) continue;
    if (!ЗВЕРЬ(т) && m.u8(UNITS + i + U.OWNER) === мой) continue;
    if (m.u32(UNITS + i + U.TARGET) !== боец) continue;
    // ТОЛЬКО ТЕ, КТО ДОСТАЁТ. Поле цели зверь держит и когда бежит к нам через полкарты, и когда
    // уже ушёл домой. Раньше сюда попадали все подряд: боец «отходил» от того, кто в десяти
    // клетках, то есть не в ту сторону, а то и стоял, считая, что его бьют трое. Владелец:
    // «мелкий если бьют — он не всегда отходит; либо не в ту сторону от атакующего, либо вообще
    // не отходит». Берём тех, кто в состоянии боя и в пределах своего удара.
    const сост = m.u8(UNITS + i + U.STATE);
    const дерётся = (сост >> 4) === 1 || сост === 0x30 || сост === 0x32;
    if (!дерётся) continue;
    if (далеко(кл(m, i), кл(m, боец)) > Math.max(1, дальность(m, i))) continue;
    б.push(i);
  }
  return б;
}

/**
 * Сколько ударов боец ещё выдержит — по САМОМУ БОЛЬНОМУ из тех, кто его сейчас бьёт.
 *
 * Считать только по текущей жертве было мало: первый замер этого файла показал, что жертву-то
 * четвёрка валит за семь секунд, а потом двое наших гибнут — их добивали ПОДОШЕДШИЕ СОСЕДИ,
 * которых правило отхода просто не видело.
 */
function ударовДо(m, боец, бьющие) {
  if (!бьющие.length) return 99;
  // СЧИТАЕМ ВСЕХ, КТО БЬЁТ, А НЕ САМОГО БОЛЬНОГО. Раньше здесь брался максимум урона одного
  // зверя — и боец, которого грызли трое, думал, что у него ещё есть время. Владелец: «начали
  // дохнуть юниты, видимо, надо лимит отступления учитывать ещё, если его несколько зверей бьют».
  // Складываем урон в секунду от каждого (у каждого свой темп: гиена бьёт раз в 0.5 с, тигр — раз
  // в 0.44 с) и переводим оставшееся время в «удары» по темпу самого быстрого из них: порог
  // владельца задан в ударах, и смысл у него — «сколько раз меня успеют ударить».
  const темп = (i) => РАСТЕНИЕ(m.u8(UNITS + i + U.TYPE))
    ? 1 : 1 / тиковНаУдар(m.u8(UNITS + i + U.TYPE));
  let уронВТик = 0, быстрейший = 0;
  for (const з of бьющие) {
    const т = темп(з);
    уронВТик += уронПо(m, з, боец) * т;
    if (т > быстрейший) быстрейший = т;
  }
  if (уронВТик <= 0) return 99;
  const тиковДоСмерти = m.u8(UNITS + боец + U.HP) / уронВТик;
  return тиковДоСмерти * быстрейший;
}

// ПРОКАЧКА ТОЛЬКО В АТАКУ. Маска обучения лежит в байте +0x0b: бит 1 — здоровье (HP), 2 — атака
// (OP), 4 — защита (DP), 8 — магия (MP), 0x10 — скорость (VP); карта раздаёт юнитам 0x17, то есть
// всё подряд. Требование владельца: «добавь сразу всем отключение прокачки всех навыков кроме
// OP» — опыт весь уходит в урон, и зверь падает ощутимо раньше. Магам магию оставляем: без неё им
// нечем работать.
const ЖИЗНИ = 1, ТОЛЬКО_АТАКА = 2, ЗАЩИТА = 4, МАГИЯ = 8, СКОРОСТЬ = 0x10;

/**
 * Выставить маску прокачки — три ступени.
 *
 * Маска лежит в байте +0x0b: 1 — жизни (HP), 2 — атака (OP), 4 — защита (DP), 8 — магия (MP),
 * 0x10 — скорость (VP). Карта раздаёт 0x17, то есть всё подряд, и опыт растекается.
 *
 * Правило владельца, последняя редакция: «посмотри, на каком уровне человек становится воином…
 * бывает, что человек изначально мускулистый, тогда воином он уже не станет, а урон может быть
 * таким же большим — это косяк. Если ОП дорос до определённого размера, тогда включаем остальные
 * два параметра; когда все вместе увеличились ещё в полтора раза, включаем всё остальное».
 *
 *   ступень 1 — только ОП (магам ещё магия: без неё им нечем работать);
 *   ступень 2 — атака доросла до ПОРОГ_ОП (70, тот же порог, по которому движок делает охотника):
 *               открываем жизни и защиту;
 *   ступень 3 — сумма трёх открытых статов (атака + макс. жизни + защита) выросла ещё в
 *               РОСТ_ДЛЯ_ОСТАЛЬНЫХ раз от того, какой она была в момент открытия второй ступени:
 *               открываем всё, магию и скорость.
 *
 * Классом теперь не меряем вовсе — только числами, поэтому мускулистый с самого начала идёт по
 * тем же ступеням, что и простолюдин.
 */
export function прокачкаВАтаку(m, бойцы, с = null) {
  const база = с ? (с.прокачкаБаза ??= new Map()) : null;
  for (const i of бойцы) {
    if (!жив(m, i)) continue;
    const т = m.u8(UNITS + i + U.TYPE);
    const маг = т >= 5 && т <= 8;
    const атака = m.u8(UNITS + i + U.ATK);
    let своё = ТОЛЬКО_АТАКА | (маг ? МАГИЯ : 0);
    if (атака >= ПОРОГ_ОП) {
      своё |= ЖИЗНИ | ЗАЩИТА;
      const сумма = атака + m.u8(UNITS + i + U.HPMAX) + m.u8(UNITS + i + U.DEF);
      if (база) {
        // Номера записей движок переиспользует после смерти, поэтому отметку храним вместе с той
        // суммой, при которой её поставили: если сумма вдруг оказалась МЕНЬШЕ отметки, это уже
        // другой боец — переписываем.
        const было = база.get(i);
        if (было === undefined || сумма < было) { база.set(i, сумма); с.прокачкаЭтап?.delete(i); }
        else if (сумма >= было * РОСТ_ДЛЯ_ОСТАЛЬНЫХ) {
          своё |= МАГИЯ | СКОРОСТЬ;
          // ЭТАПЫ 4–5 (владелец): «когда раскачали игрока до равных параметров со всеми абилками — снова
          // отключаем всё, кроме урона, и качаем урон; как только урон в два раза больше остального —
          // включаем снова все навыки и дальше остаёмся со всеми». Равные — жизни, атака и защита
          // расходятся не больше чем на ПРОКАЧКА_РАВНЫ; «остальное» — большее из жизней и защиты.
          if (ПРОКАЧКА_2) {
            const эт = (с.прокачкаЭтап ??= new Map());
            const жизни = m.u8(UNITS + i + U.HPMAX), защита = m.u8(UNITS + i + U.DEF);
            let этап = эт.get(i) || 3;
            if (этап === 3 && Math.max(атака, жизни, защита) <= Math.min(атака, жизни, защита) * ПРОКАЧКА_РАВНЫ) этап = 4;
            if (этап === 4 && атака >= 2 * Math.max(жизни, защита)) этап = 5;
            эт.set(i, этап);
            if (этап === 4) своё = ТОЛЬКО_АТАКА | (маг ? МАГИЯ : 0);
          }
        }
      }
    } else if (база) база.delete(i);
    if (m.u8(UNITS + i + U.STAT0B) !== своё) m.w8(UNITS + i + U.STAT0B, своё);
  }
}

/** Новое состояние слоя. `отходят` помнит, кто сейчас отступил и ждёт переагра. */
export const новое = () => ({ цель: 0, отходят: new Map(), ударовНаОтход: УДАРОВ_ДО_СМЕРТИ,
                              вцепились: false, здоровьеЦели: 0, отрыв: null, отдых: false, прокачаны: -99,
                              стройС: null, ударС: null, угодья: null });

// ОТРЫВ КУЧКОЙ. Правило владельца: «если на отряд сагрились больше двух зверей, весь отряд отходит
// кучкой в сторону, где наибольшее расстояние от всех зверей, на свободную полянку, и начинает по
// ней кружить, пока звери не отстанут».
//
// Два его же уточнения определяют устройство:
//   • «надо стараться дольше держать прямую дорогу, чтобы оторваться» — зверь быстрее нас, но
//     через время отстаёт сам, поэтому направление ВЫБИРАЕТСЯ РЕДКО и держится до конца отрезка;
//   • «обычно из кучи лишь пара зверей начинает преследование; алгоритм не должен запутаться от
//     того, что рядом бежит зверь» — поэтому точка оценивается не по тому, кто дышит в спину, а
//     по расстоянию от САМОЙ ТОЧКИ до всех зверей. Преследователь остаётся позади, и выбранное
//     направление от него не «портится».
// Числа подбираются замером (tools/образец_прогон.mjs), поэтому вынесены в окружение.
// Ручки читаются и из переменных окружения (стенд), и ИЗ АДРЕСНОЙ СТРОКИ (страница): любой
// параметр вида JW_ОБР_… в ссылке перебивает значение по умолчанию. Так можно сравнить два
// поведения прямо в браузере, не трогая файлы:
//   /jw/scene/tyrano — как есть, а с «?JW_ОБР_ДАЛЬНИЙ_ОТХОД=2» — с коротким отходом.
const срд = (() => {
  const е = { ...(globalThis.process?.env || {}) };
  try {
    // Длинные JW_… — для стенда, короткие латинские (hq, jev) — для ссылок: владелец просил
    // присылать адреса без русских букв и спецсимволов.
    for (const [к, з] of new URLSearchParams(globalThis.location?.search || ''))
      if (к.startsWith('JW_') || к === 'hq' || к === 'jev') е[к] = з;
  } catch {}
  return сПресетом(е);
})();
// Две группы по трое (см. шаг): опыт по плану владельца для Тирано/2, по умолчанию выключен.
const ГРУППЫ = (срд.JW_ОБР_ГРУППЫ ?? '0') === '1';
const НИЗ_У_БАЗЫ = +(срд.JW_ОБР_НИЗ_У_БАЗЫ || 0);      // >0: участок нижней группы — круг у Святилища
const НИЗ_ЧИСЛО = +(срд.JW_ОБР_НИЗ_ЧИСЛО || 0);        // >0: столько бойцов у базы, остальные охотятся
const НИЗ_КТО = срд.JW_ОБР_НИЗ_КТО || 'сильный';         // кого оставлять у базы: 'сильный' или 'слабые'
const РАЗДЕЛИТЬ_ОТ = +(срд.JW_ОБР_РАЗДЕЛИТЬ_ОТ || 6);   // со стольких бойцов делимся на две группы
// ПО УМОЛЧАНИЮ ОТРЫВ ВЫКЛЮЧЕН (99 — значит никогда), и вот почему. Прямой замер погони на высшей
// сложности: одна гиена гонится за убегающим, расстояние держится 1–3 клетки и НЕ РАСТЁТ (её
// скорость 115 против наших 20), здоровье убегающего уходит с 19 до 4 за шесть секунд. То есть
// «через время зверь отстаёт» на этой сложности не работает: наш умирает раньше, чем зверю
// надоест. Замер сцены подтверждает: с отрывом 2 убитых зверя, без него — 3, потери одинаковые.
// Код и все пороги оставлены: на других картах и сложностях, где зверьё медленнее, правило
// владельца может заработать; включается JW_ОБР_АГРОВ=3.
const АГРОВ_НА_ОТРЫВ = +(срд.JW_ОБР_АГРОВ || 3);
// Выход из отрыва — с выдержкой. Первый заход мерил только «сколько зверей держат нас целью», и
