// девяносто секунд пробегал в сумме две с половиной секунды. Поэтому уходим по-настоящему: пока
// хоть кто-то держит нас целью или ближайший зверь ближе ОТОРВАЛИСЬ клеток — бежим, и лишь когда
// и то и другое спокойно ВЫДЕРЖКА тиков подряд, считаем, что оторвались.
const ОТОРВАЛИСЬ = +(срд.JW_ОБР_ОТОРВАЛИСЬ || 5);      // клеток до ближайшего зверя — мы свободны
const ПОДПУСКАЕМ_ВО_СНЕ = +(срд.JW_ОБР_СОН_РЯДОМ || 2); // ближе этого зверь будит спящих
// До какого здоровья спим. Пробовал будить раньше, чтобы отряд не стоял столбом: при пороге 8,
