const ВСТАЁМ_НА = +(срд.JW_ОБР_ВСТАЁМ || 255);
const ВЫДЕРЖКА = +(срд.JW_ОБР_ВЫДЕРЖКА || 9);          // тиков спокойствия подряд — и ложимся спать
const ПОВТОРНАЯ_ПОПЫТКА = +(срд.JW_ОБР_ПИНОК || 12);   // столько тиков стоим — пинаем приказ заново
const ТОЧКА_УЕХАЛА = +(срд.JW_ОБР_УЕХАЛА || 3);        // на столько клеток должна сместиться цель, чтобы слать приказ заново
const ПОГОНЯ_СРОК = +(срд.JW_ОБР_ПОГОНЯ || 54);        // тиков на проверку «приближаемся ли»
const ПОГОНЯ_ШАГ = +(срд.JW_ОБР_ПОГОНЯ_ШАГ || 2);      // на столько клеток должны сократить за срок
const ЗАБЫТЬ_НА = +(срд.JW_ОБР_ЗАБЫТЬ || 540);         // столько тиков не трогаем безнадёжную жертву
const КРУГ_РАСТЕНИЯ = +(срд.JW_ОБР_РАСТЕНИЕ || 4);     // ближе этого к цветку и грибу не подходим
const ЗАПАС_ОТ_ЦВЕТКА = +(срд.JW_ОБР_ЗАПАС_ЦВЕТКА || 1);  // на столько дальше круга собираемся
const СБОР_У_ЦВЕТКА = +(срд.JW_ОБР_СБОР_ЦВЕТКА || 3);     // разброс, при котором считаем «собрались»
