const ДЕРЖАТЬ_ЦЕЛЬ = +(срд.JW_ОБР_ДЕРЖАТЬ ?? 0);          // тиков, пока выбранную цель не меняем
const ОХРАНА_ДОМА = +(срд.JW_ОБР_ОХРАНА || 2);            // столько бойцов держим у базы, когда есть сосед
const ОХРАНА_ОТ = +(срд.JW_ОБР_ОХРАНА_ОТ || 0);                // охрану выделяем, только когда бойцов не меньше
const ОХРАНА_КТО = срд.JW_ОБР_ОХРАНА_КТО || '';                 // '', 'сильный', 'слабые'
const ОХРАНА_ЛОГОВА = (срд.JW_ОБР_ОХРАНА_ЛОГОВА ?? '0') === '1';  // опыт: охрана и при логове зверя у базы
const ОХРАНА_РАДИУС = +(срд.JW_ОБР_ОХРАНА_КРУГ || 6);     // в этом круге от базы охрана и стоит
const ЧУЖИЕ_КРУГ = +(срд.JW_ОБР_ЧУЖИЕ_КРУГ || 8);         // ближе этого к чужим бойцам не охотимся
const ЗАПАС_НА_ДОБИВ = +(срд.JW_ОБР_ДОБИВ || 130) / 100;  // во столько раз урон должен обгонять лечение зверя
const ПОЛ_УРОНА = +(срд.JW_ОБР_ПОЛ_УРОНА || 10) / 100;    // ниже этой доли сырого урона их удар не падает
const УБИЙЦА_ДЕРЖИТ = (срд.JW_ОБР_УБИЙЦА ?? '0') === '1';
const УХОДИТЬ_ИЗ_ЗОН = (срд.JW_ОБР_ИЗ_ЗОН ?? '1') === '1';  // без цели не стоим в зоне зверя-убийцы
