const СТРЕЛЯТЬ_ПО_ЦВЕТАМ = (срд.JW_ОБР_СТРЕЛЬБА ?? '0') === '1';   // стрельба по цветам отложена
const ТИШИНА_ДЛЯ_ЦВЕТОВ = +(срд.JW_ОБР_ТИШИНА || 8);      // зверья ближе этого нет — можно заняться цветком
