// мамонтов; совсем впритык его могут победить, но начинают атаковать практически сразу. Надо для
// таких больших зверей чуть поднять коэффициент, небольшой множитель, не просто сумма, а чуть
// геометрическую прогрессию. Чтобы сначала подкачаться и только потом приступать к таким большим».
// Считаем «жирность» как отношение запаса жизней зверя к среднему запасу нашего бойца и возводим
// множитель запаса в эту степень:
//   пёс 33, леопард 37, тигр 65 (это ≤ 2.2 наших) → надбавки нет, запас как был, 1.5;
//   мамонт 95 при наших 30 (жирность 3.2)          → 1.5 · 2^1.0 = 3.0 — впритык уже не «по зубам».
// Важное следствие: мерка привязана к НАШЕМУ здоровью, поэтому прокачка сама открывает крупную
// добычу — подкачались вдвое, и мамонт из «жирность 3» становится «жирность 1.5».
// ПОРОГ: до него надбавки нет вовсе. Владелец: «ты слишком большой коэффициент сделал, теперь они
// на тигра не нападают, хотя легко его могут убить». Тигр (65 жизней) — это ровно вдвое наш боец,
// и он посилен; мамонт (95) — втрое, и вот он уже нет. Поэтому прогрессия начинается с 2.2 нашего
// размера: тигр проходит без надбавки, мамонт получает её полностью.
const ПОРОГ_ЖИРНОГО = +(срд.JW_ОБР_ПОРОГ_ЖИРНОГО || 2.2);
const ЖИРНЫЙ_РОСТ = +(срд.JW_ОБР_ЖИРНЫЙ || 2.0);          // основание прогрессии (1 — правило выключено)
const ЖИРНЫЙ_ПОТОЛОК = +(срд.JW_ОБР_ЖИРНЫЙ_МАКС || 4);    // выше этой жирности степень не растёт
// Насколько ротация («смена туши») сбивает урон зверя по отряду: 0.6 — на четверть с лишним.
const СВОБОДНЫЙ_ЦЕНТР = (срд.JW_ОБР_СВОБОДНЫЙ_ЦЕНТР ?? '1') === '1';   // возврат в участок — в клетку без дома
const КОНЕЦ_НЕ_В_АГРЕ = (срд.JW_ОБР_КОНЕЦ_НЕ_В_АГРЕ ?? '0') === '1';   // точки сбора/возврата — вне радиуса убийц
const ГОНЕЦ = (срд.JW_ОБР_ГОНЕЦ ?? '0') === '1';          // отправлять одного за вещью на земле
const ГОНЕЦ_РАДИУС = +(срд.JW_ОБР_ГОНЕЦ_РАДИУС || 12);    // насколько далеко от отряда
const ГОНЕЦ_ТИХО = +(срд.JW_ОБР_ГОНЕЦ_ТИХО || 6);        // ближе этого к отряду зверь — гонца не отпускаем
const ГОНЕЦ_СРОК = +(срд.JW_ОБР_ГОНЕЦ_СРОК || 1100);      // тиков на всю ходку (≈ минута)
const К_ЦЕЛИ = +(срд.JW_ОБР_К_ЦЕЛИ ?? 0);               // вес направления к добыче при отходе (0 — выкл)
const ЖЕЛАНИЕ_СРОК = +(срд.JW_ОБР_ЖЕЛАНИЕ_СРОК || 360);  // столько тиков помним, куда шли
const ПЛАН_Т2 = (срд.JW_ШТАБ_ПЛАН ?? '0') === '1';          // план второй миссии Тирано (js/ai/тирано2.js)
// ГЛАВНЫЙ (опыт владельца, Тирано/2): «чтобы прокачивался только один человек — первых двух зверей
// пусть он убьёт, а остальные пусть идут нормально охотиться. Он остаётся на охране, ему уже хватит сил
// одному. Остальные слабые пусть уходят и охотятся без последнего удара, им не надо возвращаться
// домой, и они не должны бояться мамонтов — напрямую бегут до нужных зверей; если после атаки за ними
// ещё гонится жирный мамонт или слишком сильный — тогда убегаем». JW_ОБР_ГЛАВНЫЙ=N — сколько убийств
// отдать главному (0 — выкл).
// ОЦЕНКА ДОБЫЧИ (владелец): «выбираем зверя по силам, но так, чтобы рядом было меньше других зверей и
// сильных; каждый зверь рядом добавляет вес, сильный — больше; расстояние тоже важно, но ниже опасности;
// опасность делится на силу отряда». оценка = расстояние·К_ДИСТ + опасность·К_ОПАС, меньше — лучше;
// опасность = Σ по зверям в ОЦ_РАДИУС от добычи (1 + К_СИЛ·сила зверя/сила отряда)·(1 − д/(R+1)),
// сила = жизни·атака (отряда — сумма). Жёсткие запреты «рядом непосильный» и «гуща» при ней выключены.
const ОЦЕНКА = (срд.JW_ОБР_ОЦЕНКА ?? '0') === '1';
const ОЦ_ДИСТ = +(срд.JW_ОБР_ОЦ_ДИСТ ?? 1), ОЦ_ОПАС = +(срд.JW_ОБР_ОЦ_ОПАС ?? 6), ОЦ_СИЛ = +(срд.JW_ОБР_ОЦ_СИЛ ?? 4);
const ОЦ_РАДИУС = +(срд.JW_ОБР_ОЦ_РАДИУС ?? 8);
// РАНЕНЫЙ ПОДХОДИТ ПОСЛЕДНИМ (владелец): «если жизни ниже, чем 4 удара хищника, стараться подойти к зверю
// попозже остальных: пока я ближе всех — стою жду, когда я не первый — начинаю движение». JW_ОБР_РАНЕНЫЙ=N —
// сколько ударов зверя по бойцу считать запасом (0 — выкл). Не действует, если зверь бьёт его самого
// или если здоровых в отряде нет.
const РАНЕНЫЙ_УДАРОВ = +(срд.JW_ОБР_РАНЕНЫЙ || 0);
const НЕ_ЗА_СПИНОЙ = (срд.JW_ОБР_НЕ_ЗА_СПИНОЙ ?? '0') === '1';
const ПОХОД_ВМЕСТЕ = (срд.JW_ОБР_ПОХОД_ВМЕСТЕ ?? '0') === '1';   // в походе к добыче не растягиваться, дохлый не впереди
const ОТРЫВ_ПОХОДА = +(срд.JW_ОБР_ОТРЫВ_ПОХОДА || 3);   // не стоять в коридоре отхода битого (владелец)
const ВРОЗЬ = (срд.JW_ОБР_ВРОЗЬ ?? '0') === '1';           // доросшие охотники фармят каждый сам
const ВРОЗЬ_ПРОТИВ = String(срд.JW_ОБР_ВРОЗЬ_ПРОТИВ || '23,22').split(',').map(Number);   // кого должен бить один (пёс, леопард)
const ВРОЗЬ_ЗАПАС = +(срд.JW_ОБР_ВРОЗЬ_ЗАПАС || 0.6);   // в поединке теряет не больше этой доли жизни
const ОХРАНА_ПО_УГРОЗЕ = (срд.JW_ОБР_ОХРАНА_ПО_УГРОЗЕ ?? '0') === '1';   // охранник — только если у базы опасные логова
const ОХРАНА_УГРОЗА_Р = +(срд.JW_ОБР_ОХРАНА_УГРОЗА_Р || 10);              // радиус «логова у базы»
const ГЛАВНЫЙ_ЖДАТЬ = +(срд.JW_ОБР_ГЛАВНЫЙ_ЖДАТЬ || 1100);     // ~60 с: не дождались двух убийств — охранник всё равно
const НЕ_СПИНОЙ_К_СТЕНЕ = (срд.JW_ОБР_НЕ_СПИНОЙ ?? '0') === '1';   // бой с опасным зверем — не спиной к воде/стене
const ЗА_СПИНОЙ_НАДО = +(срд.JW_ОБР_ЗА_СПИНОЙ || 5);                // столько свободных клеток позади (из 10–12)
const ВЫМАНИВАТЬ = (срд.JW_ОБР_ВЫМАНИВАТЬ ?? '0') === '1';     // задание «убить племя»: выманивать врагов по одному
const ВЫМАН_ОТРЯД = +(срд.JW_ОБР_ВЫМАН_ОТРЯД || 6);             // выманиваем, только когда бойцов не меньше
const ВЫМАН_ПОГОНЯ = +(срд.JW_ОБР_ВЫМАН_ПОГОНЯ || 6);            // дальше стольких от места сбора за жертвой не бежим
const ВЫМАН_ЗАПАС_КЛЕТОК = +(срд.JW_ОБР_ВЫМАН_КЛЕТОК || 2);      // запас к кругу обзора соседа жертвы
const ВЫМАН_ЗАПАС = +(срд.JW_ОБР_ВЫМАН_ЗАПАС || 1.5);             // запас силы кучи против жертвы (1 — с потерями)
const ЦЕЛИ_МИССИИ = (срд.JW_ОБР_ЦЕЛИ_МИССИИ ?? '1') === '1';    // захват (м6, м8) и артефакт (м5)
const ЗАХВАТ_ЗАПАС = +(срд.JW_ОБР_ЗАХВАТ_ЗАПАС || 1.2);           // армия сильнее охраны цели во столько раз
const ЗАХВАТ_ОТРЯД = +(срд.JW_ОБР_ЗАХВАТ_ОТРЯД || 8);             // со стольких бойцов армия идёт на захват
const МЯСО_РОВНО = (срд.JW_ОБР_МЯСО_РОВНО ?? '1') === '1';   // мясо берёт тот, у кого ноша меньше
const ГЛАВНЫЙ_УБИЙСТВ = +(срд.JW_ОБР_ГЛАВНЫЙ || 0);
// ГЛАВНЫЙ_СОЛО=1 (владелец): делимся не по числу убийств, а «как только один из отряда может один убить
// собаку и гиену» — главный побеждает в дуэль каждого зверя, чьё логово у базы (табличные статы: такими
// они возрождаются), теряя не больше ГЛАВНЫЙ_ЗАПАС его жизней. Тогда он остаётся охранять, трое — на охоту.
const ГЛАВНЫЙ_СОЛО = (срд.JW_ОБР_ГЛАВНЫЙ_СОЛО ?? '0') === '1';
const ГЛАВНЫЙ_ЗАПАС = +(срд.JW_ОБР_ГЛАВНЫЙ_ЗАПАС ?? 0.7);
// Насколько смелы охотники после разделения: 2 — совсем (к добыче напрямую, выпасы убийц не обходят);
// 1 — не держат дистанцию и не бегут от стоящего рядом, но добычу на выпасе мамонта/тигра не выбирают.
const ГЛАВНЫЙ_СМЕЛО = +(срд.JW_ОБР_ГЛАВНЫЙ_СМЕЛО || 2);
const К_ДОБЫЧЕ_ДО = +(срд.JW_ОБР_К_ДОБЫЧЕ_ДО || 0);   // >0: бежим от погони к добыче, пока до неё больше N клеток (опыт: 4 → хуже)
const ЛАСТХИТ = срд.JW_ОБР_ЛАСТХИТ || 'ровно';           // 'ровно' | 'главный' | 'нет'
const ЛАСТХИТ_ДОПУСК = +(срд.JW_ОБР_ЛАСТХИТ_ДОПУСК || 24);  // на сколько шагов можно затянуть бой ради прокачки
const ЛАСТХИТ_ЗДОРОВЬЕ = +(срд.JW_ОБР_ЛАСТХИТ_ЗДОРОВЬЕ ?? 50);  // все бьющие не ниже стольких % жизней
const ЛАСТХИТ_ЗАПАС = +(срд.JW_ОБР_ЛАСТХИТ_ЗАПАС ?? 2);          // и зверь по зубам с таким запасом
const ЛАСТХИТ_УДАР = +(срд.JW_ОБР_ЛАСТХИТ_УДАР ?? 10);           // удар зверя не больше стольких % жизней бойца
const РОТ = (срд.JW_ОБР_РОТ ?? '0') === '1';              // ротация раненых (опыт старта Тирано/2)
const РОТ_ПОРОГ = +(срд.JW_ОБР_РОТ_ПОРОГ || 53);          // % жизней: на мне зверь — отхожу
const РОТ_НАЗАД = +(срд.JW_ОБР_РОТ_НАЗАД || 67);          // % жизней: возвращаюсь в бой
const МЕСТА_У_ЦЕЛИ = (срд.JW_ОБР_МЕСТА ?? '1') === '1';   // лишние у цели ждут на втором кольце
const ПОДХОД_СРОК = +(срд.JW_ОБР_ПОДХОД_СРОК || 180);          // столько тиков даём дойти пешком
const ЗАСТРЯЛ_НА_ПОДХОДЕ = +(срд.JW_ОБР_ЗАСТРЯЛ_ПОДХОД ?? 54);   // тиков стоим в «иду бить» — повторить приказ
const РЕАКЦИЯ = +(срд.JW_ОБР_РЕАКЦИЯ || 0);             // тиков на выход из-под удара; 0 — не учитывать
const КОЭФ_РОТАЦИИ = +(срд.JW_ОБР_РОТАЦИЯ || 0.6);
// Запас для решения «бежать от сильного». Он НАМЕРЕННО МЕНЬШЕ, чем запас для выбора добычи: одно
// дело не лезть на тигра самим, другое — удирать от него, когда он уже пришёл. Замер порогов по
// зверю (размен.mjs, с учётом ротации): тигр у Тирано держится до 1.30, у Moospell до 1.60,
// мамонт — до 0.85. Порог 0.9 оставляет тигра в драке, а от мамонта уводит.
const ЗАПАС_ОТ_СИЛЬНОГО = +(срд.JW_ОБР_ЗАПАС_СИЛЬНОГО || 0.9);
// На столько клеток уходит битый, когда переагрить зверя не на кого (см. отход).
const ДАЛЬНИЙ_ОТХОД = +(срд.JW_ОБР_ДАЛЬНИЙ_ОТХОД || 5);
const ПОДМОГА_РЯДОМ = +(срд.JW_ОБР_ПОДМОГА || 4);        // товарищ в стольких клетках — есть кому принять агр
// Запрет на мясо, когда зверь рядом, я тоже придумал сам: владелец говорил только «сбор мяса не
// должен отменяться». Выключено; включается ручкой.
const МЯСО_НЕ_БЛИЖЕ = +(срд.JW_ОБР_МЯСО_НЕ_БЛИЖЕ || 0);  // ближе этого стоит зверь — мясо подождёт
const ОТХОД_СРОК = +(срд.JW_ОБР_ОТХОД_СРОК || 54);       // дольше этого дальний отход не тянем
// Доводка «постоял под ударами — уходи дальше» была моей выдумкой поверх правила владельца и
// только добавляла беготни. Выключено (большое число = никогда); правило про дальний отход, когда
// переагрить не на кого, живёт там, где он его и задал — в момент решения об отходе.
const ПЕРЕАГР_СРОК = +(срд.JW_ОБР_ПЕРЕАГР || 999999);
// «БИТЫЙ» — ЭТО КРАСНАЯ ПОЛОСКА, и только она. Долю жизней я придумал сам, владелец такого не
// говорил; его определение давно и дословно: «битый значит жизней мало, на красной полоске».
// Ручка оставлена на случай, если он попросит порог помягче (0 — правило по одной полоске).
const ДОЛЯ_ТЫЛА = +(срд.JW_ОБР_ДОЛЯ_ТЫЛА || 0) / 100;
const ЗДОРОВЫХ_ХВАТИТ = +(срд.JW_ОБР_ЗДОРОВЫХ || 2);     // столько целых бойцов — битый отдыхает
// Сколько соседних клеток должно быть свободно, чтобы точка отхода не была углом (см. неТупик).
const ВЫХОДОВ_НАДО = +(срд.JW_ОБР_ВЫХОДОВ_ОТХОД || 5);
const ИСКАТЬ_РЯДОМ = +(срд.JW_ОБР_ИСКАТЬ_РЯДОМ || 3);    // на столько клеток вокруг ищем замену
// Рядом с непосильным зверем не охотимся вовсе: добыча в двух шагах от мамонта — это драка с
// мамонтом. Владелец: «основной момент — они должны избегать в начале жирных животных».
const КРУГ_НЕПОСИЛЬНОГО = +(срд.JW_ОБР_КРУГ_ЖИРНОГО || 2);
// ГУЩА ЗВЕРЬЯ. Владелец: «они прям проваливаются туда и теряют одного солдата, потому что их
// окружают звери со всех сторон и им отойти некуда даже; если вокруг близко много зверей, надо
// сразу выходить из этой кучи». Отсюда три числа: в каком радиусе считаем «вокруг», сколько
// зверья в нём — уже гуща, и как далеко от гущи держаться при выборе добычи.
const КРУГ_КУЧИ = +(срд.JW_ОБР_КРУГ_КУЧИ || 4);       // в этом радиусе считаем зверьё вокруг точки
const ГУЩА = +(срд.JW_ОБР_ГУЩА || 4);                 // столько зверья рядом — это гуща, уходим
const ГУЩА_ЦЕЛИ = +(срд.JW_ОБР_ГУЩА_ЦЕЛИ || 4);       // добычу с таким числом соседей не берём
// Сколько тиков жертве можно не терять здоровье, пока мы считаем, что «вцепились» (18 тиков = 1 с).
const ЦЕПКОСТЬ = +(срд.JW_ОБР_ЦЕПКОСТЬ || 108);
// С какой ноши боец идёт разгружаться на склад и сколько тиков ему на это даётся.
// В режиме двух групп сдают по слову владельца: «как набрали в группе 3000 мяса — идут все вместе».
// Одиночный порог — чуть ниже перегруза движка (ноша ≥ HPmax·64 = 1920 у простолюдина, 0x17361), иначе
// движок сам погонит перегруженного на склад в одиночку.
const ОТНЕСТИ_ОТ = +(срд.JW_ОБР_ОТНЕСТИ || (ГРУППЫ ? 1800 : 400));
const ОТНЕСТИ_ОТРЯДОМ = +(срд.JW_ОБР_ОТНЕСТИ_ОТРЯДОМ || (ГРУППЫ ? 3000 : 700));  // столько у отряда вместе — идём сдавать все
const ДОСТАВКА_СРОК = +(срд.JW_ОБР_ДОСТАВКА_СРОК || 1800);     // дольше этого доставку не тянем
const ДОСТАВКА_СТОИТ = +(срд.JW_ОБР_ДОСТАВКА_СТОИТ || 180);   // столько тиков никто не сдвинулся — доставка встала
const ДОСТАВКА_ПАУЗА = +(срд.JW_ОБР_ДОСТАВКА_ПАУЗА || 360);   // и столько её не начинаем снова
const ДОСТАВКА_УСТУПАЕТ = +(срд.JW_ОБР_УСТУПАЕТ ?? 8);          // обидчик ближе — доставка уступает тревоге
const НЕСТИ_СРОК = +(срд.JW_ОБР_НЕСТИ_СРОК || 540);
// На «домашних» миссиях отряд держится в этом квадрате вокруг базы и дальше не уходит.
// Слой штаба: общие решения поверх отряда (js/ai/штаб.js). Включается ссылкой
// /jw/scene/tyrano/1?hq=1 или галочкой «штаб» в переключателе сцены.
//
